import{z as B,x as o,o as s,c as n,q as i,j as l,D as E,d as e,s as A,S as d,b as r}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"背压","description":"","frontmatter":{"title":"背压","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stream-backpressure.md","filePath":"cs/stream-backpressure.md","lastUpdated":1791063341000}'),p={name:"cs/stream-backpressure.md"};function c(m,a,u,C,b,h){const t=o("Mermaid");return s(),n("div",null,[a[2]||(a[2]=i('<h1 id="背压" tabindex="-1">背压 <a class="header-anchor" href="#背压" aria-label="Permalink to &quot;背压&quot;">​</a></h1><div class="epigraph"><p>背压是让消费者对生产者说「慢一点」的机制。没有它，系统的每一层都在替下游攒一笔还不上的债——债的名字叫无界缓冲。</p><footer>—— 据 Reactive Streams 与 Flink credit 流控公开设计；RFC 9110/9112 流控语义整理</footer></div><p><a href="/cs/stream-state">上一课</a>把状态放进后端与检查点；状态暴涨最常见的推手是速率不匹配。本课钉背压：当算子消费得比上游生产得慢，速率信号如何向上游传播、在哪里积压、如何诊断与解除。<a href="/cs/app-backpressure">应用层背压</a>已在网络课的应用层立过原理——窗口、有界阻塞、显式 request；本课讲同一原理在数据流引擎里的形态，以及流系统特有的两个连锁反应。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数据流引擎的每条算子边上有缓冲队列。下游慢，队列满，之后发生什么决定系统命运：队列无界，换 OOM；直接丢弃，换正确性；阻塞上游，换延迟。选阻塞就必须回答三件事：信号怎么传（信用、停等还是退让）、传多快、以及传到源头之后源听不听。流系统还有两处特有连锁：上游停，<a href="/cs/stream-watermark">watermark</a> 也停，窗口关不了——速率问题立刻变成正确性问题；barrier 跟数据一起走，检查点也会停——速率问题又变成恢复点问题。</p><p><span class="marginnote">术语翻译：背压（backpressure）就是让「下游消费得慢」这件事像水流顶回来的压力一样，沿着算子边逐级上传到数据源，让源头自动降速——不是靠运维在中间拼命调缓冲，而是让系统自己把「我吃不下」这句话传回去。</span></p><p><span class="marginnote">为什么重要：没有背压时，速率不匹配被无界队列悄悄掩盖——表面看一切正常，延迟在涨、内存也在涨，直到一次大促把队列撑爆、进程 OOM，几小时的状态一夜归零。有背压的系统在撑不住的第一秒就开始减速，把故障换成延迟。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>credit 流控：接收方以空闲缓冲数为信用，发送方只在有信用的通道上发数据，并附带自己的积压量让调度看得见；接收方处理完一批补给信用。这与 <a href="/cs/tcp-window">TCP 滑动窗口</a>同构，只是对象从字节变成记录批。诊断按三态看每个算子：busy——瓶颈在它自己；backpressured——瓶颈在下游，它只是传话；idle——上游没喂饱。输出队列长度与输入输出速率差指出积压位置。解除按序排查：并行化瓶颈算子、批量化外部 I/O、异步 I/O 但限并发容量、或按第三课的迟到合同显式丢弃（load shedding）。</p><p><span class="marginnote">credit 的在途量上限是接收方缓冲深度，与往返时延无关——停等协议才让 RTT 进吞吐公式。把算子丢进无界线程池或无界队列，等于亲手拆掉背压，OOM 只是时间问题。</span></p><p>诊断三态时沿着速率差从源头查到瓶颈，一条链路上的位置一眼可辨。</p>',11)),(s(),l(d,null,{default:E(()=>[A(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E6%BA%90%22%5D%20--%3E%7C%22%E9%80%9F%E7%8E%87%E5%B7%AE%E2%89%880%22%7C%20A%5B%22%E7%AE%97%E5%AD%90A%3A%20idle%22%5D%0A%20%20A%20--%3E%7C%22%E9%80%9F%E7%8E%87%E5%B7%AE%E2%89%880%22%7C%20B%5B%22%E7%AE%97%E5%AD%90B%3A%20busy%20%E7%93%B6%E9%A2%88%22%5D%0A%20%20B%20--%3E%7C%22%E9%80%9F%E7%8E%87%E5%B7%AE%E5%A4%A7%3A%20%E7%A7%AF%E5%8E%8B%E5%9C%A8%E6%AD%A4%22%7C%20C%5B%22%E7%AE%97%E5%AD%90C%3A%20backpressured%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%B1%87%22%5D%0A%20%20B%20--%3E%20FIX%5B%22%E5%B9%B6%E8%A1%8C%E5%8C%96B%20%2F%20%E6%89%B9%E9%87%8FI%2FO%20%2F%20%E5%BC%82%E6%AD%A5%E9%99%90%E5%B9%B6%E5%8F%91%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("背压不是故障，是设计：有界缓冲加信用，把「消费者跟得上」从祈祷变成结构。它与检查点的交互在第四课埋过：barrier 要跟数据一起过边，下游不消费，barrier 过不去，对齐检查点停摆——非对齐 barrier 把在途记录写进快照，正是为背压场景设计。它与 watermark 的交互是第三课的镜像：最慢通道冻结全局进度，空闲检测与背压解除是同一件事的两面。环状图（迭代流）里背压成环即死锁：环上没有「最上游」可停，必须靠切断或物化一条边打破。没有背压能力的系统只能二选一：像 "),r("a",{href:"/cs/aqm-red-codel"},"AQM"),e(" 那样主动丢弃保延迟，或像 "),r("a",{href:"/cs/bufferbloat"},"bufferbloat"),e(" 那样无界积压保吞吐——丢弃必须落在迟到合同上，否则等于静默改答案。")],-1)),(s(),l(d,null,{default:E(()=>[A(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E4%B8%8A%E6%B8%B8%E7%AE%97%E5%AD%90%22%5D%20--%3E%7C%22%E6%95%B0%E6%8D%AE%20%2B%20%E7%A7%AF%E5%8E%8B%E9%87%8F%22%7C%20Q%5B%22%E6%9C%89%E7%95%8C%E7%BC%93%E5%86%B2%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20OP%5B%22%E4%B8%8B%E6%B8%B8%E7%AE%97%E5%AD%90%EF%BC%9A%E6%B6%88%E8%B4%B9%E6%85%A2%22%5D%0A%20%20OP%20--%3E%7C%22%E4%BF%A1%E7%94%A8%EF%BC%9A%E7%A9%BA%E9%97%B2%E7%BC%93%E5%86%B2%E6%95%B0%22%7C%20SRC%0A%20%20FULL%5B%22%E9%98%9F%E5%88%97%E6%BB%A1%EF%BC%9A%E4%B8%8A%E6%B8%B8%E5%81%9C%E5%8F%91%22%5D%20--%3E%20WM%5B%22watermark%20%E5%81%9C%EF%BC%9A%E7%AA%97%E5%8F%A3%E5%BB%B6%E8%BF%9F%E3%80%81%E6%A3%80%E6%9F%A5%E7%82%B9%E5%81%9C%E6%91%86%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写具体引擎的指标名与告警阈值；判据是通用的：分清 busy、backpressured、idle，再对症。丢弃策略要接第三课的迟到合同——丢了什么、丢了多少，必须可观测可辩护。也不要把背压与限流混为一谈：限流是入口有意控制速率，背压是下游被动申告容量；前者在 API 网关，后者在算子边。后课默认：引擎的边是有界通道，速率不匹配在边上是可见的、可诊断的，不是神秘的。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>背压靠有界缓冲加 credit：在途量由缓冲深度决定，与 RTT 无关。</li><li>诊断三态：busy 是自己慢，backpressured 是下游慢，idle 是上游没喂饱。</li><li>背压停摆会连锁到 watermark 与检查点：速率问题同时是正确性问题。</li><li>环状图的背压是死锁，必须切断或物化一条边；无界队列等于拆除背压。</li><li>出处：Reactive Streams 规范；Flink credit 流控公开设计；对照 TCP 窗口、应用层背压与 AQM 课。</li></ul>',4))])}const F=B(p,[["render",c]]);export{k as __pageData,F as default};
